package com.luminor.tavernquest.feature.board
import androidx.lifecycle.*;import com.luminor.tavernquest.domain.model.*;import com.luminor.tavernquest.domain.usecase.contract.*;import dagger.hilt.android.lifecycle.HiltViewModel;import javax.inject.Inject;import kotlinx.coroutines.flow.*;import kotlinx.coroutines.launch
@HiltViewModel class BoardViewModel @Inject constructor(private val generate:GenerateDailyBoardUseCase,get:GetDailyBoardUseCase,private val acceptUse:AcceptContractUseCase):ViewModel(){private val filter=MutableStateFlow<ContractCategory?>(null);private val msg=MutableStateFlow<String?>(null);val ui=combine(get(),filter,msg){list,cat,m->BoardUiState(false,list.filter{cat==null||it.template.category==cat},cat,m)}.stateIn(viewModelScope,SharingStarted.WhileSubscribed(5000),BoardUiState());init{viewModelScope.launch{generate()}};fun filter(c:ContractCategory?){filter.value=c};fun accept(id:String){viewModelScope.launch{if(!acceptUse(id))msg.value="Limite de cinco contratos aceitos atingido."}}}
